<?php require_once __DIR__.'/../includes/layout.php'; require_permission('roles.manage'); if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf(); db()->prepare('INSERT INTO roles(name,description) VALUES (?,?) ON DUPLICATE KEY UPDATE description=VALUES(description)')->execute([$_POST['name'],$_POST['description']]); audit('role_change','roles');} $roles=db()->query('SELECT * FROM roles ORDER BY name')->fetchAll(); dashboard_header('Manage Roles'); ?><div class="glass-card p-4"><form method="post" class="row g-2 mb-3"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><div class="col"><input name="name" class="form-control" placeholder="Role name"></div><div class="col"><input name="description" class="form-control" placeholder="Description"></div><div class="col-auto"><button class="btn btn-premium">Add Role</button></div></form><ul class="list-group"><?php foreach($roles as $r):?><li class="list-group-item bg-transparent"><?=e($r['name'])?> <small><?=e($r['description'])?></small></li><?php endforeach;?></ul></div><?php dashboard_footer(); ?>
